mapper.select:
SELECT s.surveyid AS surveyNum, s.sub AS surveySub, s.code AS surveyCode, s.rdate AS surveyData, sc.surveytype AS surveytype,
sc.surveyid AS subCode, sc.surveytitle AS surveytitle, sc.surveycnt AS surveycnt
FROM p_survey s, p_survey_cont sc WHERE s.surveyid = sc.surveyid AND s.surveyid = #{num}
